/*!
 * wega-music-endless4.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "endless4" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * ENDLESS 4 (floors 41-50) - supplied by the player. Loops with a crossfade from 293.5 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-endless4.js] load wega-music.js first"); return; }
  D.endless4 = {
    title: "ENDLESS 4 (floors 41-50)",
    credit: "supplied by the player",
    duration: 298.057,
    loopStart: 0.0,
    loopEnd: 293.5,
    xfade: 2.5,
    gain: 0.76,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("endless4") < 0) W.tracks.push("endless4");
  if (W.onPack) W.onPack("endless4");
})(typeof window !== "undefined" ? window : globalThis);
